/* ============================================================
   智能评论筛选：原型样式
   视觉基线：抖音手游直播间（视频色延展背景 + 半透明气泡公屏）
   视口：390 × 844
   ============================================================ */

:root{
  /* 视频延展背景（取自峡谷绿） */
  --bg-1:   #313a2c;
  --bg-2:   #3b462f;
  --bg-3:   #445034;
  --bg-4:   #333c2a;

  /* 公屏气泡 */
  --bubble:     rgba(0,0,0,.36);
  --bubble-2:   rgba(0,0,0,.26);

  /* 深色功能面板 */
  --surface:    #17181c;
  --surface-2:  #212329;
  --line:       rgba(255,255,255,.08);
  --line-2:     rgba(255,255,255,.14);

  --txt:    #ffffff;
  --txt-2:  rgba(255,255,255,.72);
  --txt-3:  rgba(255,255,255,.42);

  --accent:      #fe2c55;
  --accent-soft: rgba(254,44,85,.16);
  /* 次级强调色 */
  --accent-2:      #7c8cff;
  --accent-2-soft: rgba(124,140,255,.16);
  --nick:        #6fe3c4;   /* 公屏昵称青绿 */
  --blue:        #7db8ff;
  --red:         #ff7b7b;

  --ease:       cubic-bezier(.22,.61,.36,1);
  --ease-sheet: cubic-bezier(.16,.84,.34,1);
}

*{ margin:0; padding:0; box-sizing:border-box; -webkit-tap-highlight-color:transparent; }
html,body{ height:100%; }

body{
  background:#0b0c0e;
  background-image:radial-gradient(900px 620px at 50% 8%, #16181d 0%, #0b0c0e 62%);
  font-family:-apple-system,BlinkMacSystemFont,"SF Pro SC","PingFang SC",
              "HarmonyOS Sans SC","Microsoft Yahei",sans-serif;
  color:var(--txt);
  display:flex; align-items:center; justify-content:center;
  min-height:100vh;
  overflow-x:hidden;
}
.stage{
  padding:24px;
  display:flex; align-items:center; justify-content:center;
  gap:56px;
}

/* 固定尺寸手机原型的响应式承载层：
   手机内部仍按 390 × 844 设计，只缩放桌面展示尺寸。 */
.phone-frame{
  position:relative;
  flex:none;
  width:414px;
  height:868px;
}

/* Try the demo 的位置提示：贴着手机外框，只负责指出当前操作区域。 */
.step-pointer{
  --pointer-x:calc(100% + 15px);
  --pointer-y:92%;
  position:absolute; left:0; top:0; z-index:60;
  width:26px; height:26px;
  pointer-events:none;
  opacity:0;
  transform:translate3d(var(--pointer-x),var(--pointer-y),0) translate(-50%,-50%);
  transition:opacity .18s linear;
}
.step-pointer.is-positioned{
  transition:transform .32s cubic-bezier(.22,1,.36,1), opacity .18s linear;
}
.step-pointer.is-visible{ opacity:1; }
.step-pointer::before{
  content:"";
  position:absolute; inset:0;
  border-radius:50%;
  background:radial-gradient(circle, rgba(174,160,255,.24) 0%, rgba(174,160,255,.1) 42%, rgba(174,160,255,0) 72%);
  opacity:.48;
}
.step-pointer-tip{
  position:absolute; left:50%; top:50%;
  width:0; height:0;
  opacity:.58;
  transform:translate(-50%,-50%) scale(.92);
}
.step-pointer.is-right .step-pointer-tip{
  border-top:5px solid transparent;
  border-bottom:5px solid transparent;
  border-right:9px solid rgba(190,180,255,.88);
}
.step-pointer.is-left .step-pointer-tip{
  border-top:5px solid transparent;
  border-bottom:5px solid transparent;
  border-left:9px solid rgba(190,180,255,.88);
}
.step-pointer.is-bottom .step-pointer-tip{
  border-left:5px solid transparent;
  border-right:5px solid transparent;
  border-bottom:9px solid rgba(190,180,255,.88);
}
.step-pointer.is-cue::before{ animation:stepPointerHalo .9s ease-in-out infinite; }
.step-pointer.is-cue .step-pointer-tip{ animation:stepPointerPulse .9s ease-in-out infinite; }
.step-pointer.is-reminder::before{ animation:stepPointerHalo 1.15s ease-in-out infinite; }
.step-pointer.is-reminder .step-pointer-tip{ animation:stepPointerPulse 1.15s ease-in-out infinite; }
@keyframes stepPointerHalo{
  0%,100%{ opacity:.34; transform:scale(.82); }
  48%{ opacity:.82; transform:scale(1.12); }
}
@keyframes stepPointerPulse{
  0%,100%{ opacity:.5; transform:translate(-50%,-50%) scale(.9); }
  48%{ opacity:1; transform:translate(-50%,-50%) scale(1.1); }
}

/* 项目说明：手机左侧（参考稿的 narration/thesis/step 排版语言） */
.intro{
  width:420px; max-width:88vw;
  position:relative;
  display:flex; flex-direction:column; gap:18px;
  color:#fff;
}

/* 标题区 */
.intro-head h1{
  font-size:26px; font-weight:680; letter-spacing:-.4px;
  line-height:1.15;
  color:#fff;
}
.intro-head h1 em{
  font-style:normal; font-weight:400;
  color:rgba(255,255,255,.42);
  font-size:16px; margin-left:6px; letter-spacing:.4px;
}
.intro-meta-row{
  display:flex; align-items:center; justify-content:space-between; gap:14px;
  margin-top:9px;
}
.intro-sub{
  font-size:12.5px; letter-spacing:.2px;
  color:rgba(255,255,255,.42);
  white-space:nowrap;
}
.intro-tabs{
  position:relative;
  display:flex;
  align-items:center;
  gap:24px;
  margin-top:18px;
  border-bottom:1px solid rgba(255,255,255,.09);
}
.intro-tab{
  position:relative;
  padding:0 0 10px;
  border:0;
  background:transparent;
  color:rgba(255,255,255,.42);
  font-family:inherit;
  font-size:12px;
  font-weight:560;
  line-height:1;
  cursor:pointer;
  transition:color .2s ease;
}
.intro-tab::after{
  content:"";
  position:absolute;
  left:0; right:0; bottom:-1px;
  height:2px;
  border-radius:999px;
  background:var(--accent-2);
  opacity:0;
  transform:scaleX(.55);
  transition:opacity .2s ease, transform .28s cubic-bezier(.22,1,.36,1);
}
.intro-tab:hover{ color:rgba(255,255,255,.7); }
.intro-tab.is-active{
  color:rgba(255,255,255,.92);
}
.intro-tab.is-active::after{
  opacity:1;
  transform:scaleX(1);
}
.intro-tab:focus-visible{
  outline:1px solid rgba(124,140,255,.72);
  outline-offset:4px;
}

.intro-content{
  position:relative;
  min-height:386px;
}
.intro-overview{
  opacity:1; transform:translateY(0); pointer-events:auto;
  transition:opacity .18s linear, transform .22s cubic-bezier(.22,1,.36,1);
}
.intro.is-open .intro-overview{
  opacity:0; transform:translateY(-4px); pointer-events:none;
}
.intro-thesis{
  max-width:19em;
  font-size:18px; line-height:1.55; font-weight:520;
  letter-spacing:-.15px;
  color:rgba(255,255,255,.86);
}
.intro-context{
  margin-top:0;
  border-top:0;
}
.intro-context-row{
  display:grid; grid-template-columns:44px 1fr; gap:12px;
  padding:11px 0;
  border-bottom:1px solid rgba(255,255,255,.065);
}
.intro-context dt,
.intro-metrics-label{
  font-size:11px; line-height:1.65; font-weight:600;
  color:rgba(255,255,255,.44);
}
.intro-context dd{
  font-size:12.5px; line-height:1.65;
  color:rgba(255,255,255,.62);
}
.intro-idea{
  margin-top:19px;
}
.intro-idea-label{
  font-size:10px; line-height:1; font-weight:650; letter-spacing:1.1px;
  text-transform:uppercase;
  color:rgba(139,151,255,.86);
}
.intro-idea h2{
  margin-top:7px;
  font-size:16px; line-height:1.35; font-weight:650;
  letter-spacing:-.1px;
  color:rgba(255,255,255,.94);
}
.intro-idea p{
  margin-top:7px;
  font-size:12.5px; line-height:1.65;
  color:rgba(255,255,255,.58);
}
.intro-idea b{
  color:rgba(255,255,255,.92);
  font-weight:580;
}
.intro-metrics{
  display:block;
  margin-top:13px;
  padding-top:11px;
  border-top:1px solid rgba(255,255,255,.075);
}
.intro-metrics-label{ display:block; }
.intro-metrics-list{
  display:grid;
  grid-template-columns:minmax(0,.82fr) minmax(0,1.28fr);
  gap:18px;
  margin-top:13px;
  padding-left:0;
  min-width:0;
}
.intro-metric{
  display:flex;
  flex-direction:column;
  align-items:flex-start;
  min-width:0;
}
.intro-metric + .intro-metric{
  padding-left:0;
  border-left:0;
}
.intro-metric strong,
.intro-metric span{
  display:block;
}
.intro-metric strong{
  padding:0;
  border:0;
  background:transparent;
  font-size:10.5px; line-height:1.35; font-weight:620;
  color:rgba(139,151,255,.86);
}
.intro-metric span{
  margin-top:8px;
  font-size:9.5px; line-height:1.45;
  color:rgba(255,255,255,.4);
}

.logic-panel{
  position:absolute; inset:0; z-index:2;
  width:100%;
  opacity:0; visibility:hidden; pointer-events:none;
  transform:translateY(4px);
  transition:
    opacity .22s linear,
    transform .22s cubic-bezier(.22,1,.36,1),
    visibility 0s linear .22s;
}
.intro.is-open .logic-panel{
  opacity:1; visibility:visible; pointer-events:auto;
  transform:translateY(0);
  transition-delay:0s;
}
.logic-panel-inner{
  padding:0;
}
.logic-kicker{
  font-size:10px; font-weight:650; letter-spacing:1.1px;
  color:rgba(139,151,255,.86);
}
.logic-head h2{
  margin-top:7px;
  font-size:18px; line-height:1.3; font-weight:650;
  letter-spacing:-.15px;
  color:rgba(255,255,255,.94);
}
.logic-head > p:last-child{
  margin-top:6px;
  font-size:12px; line-height:1.55;
  color:rgba(255,255,255,.46);
}
.logic-flow{
  position:relative;
  margin-top:17px;
}
.logic-mode{
  padding-top:0;
}
.logic-mode-head{
  display:grid; grid-template-columns:minmax(0,1fr) auto;
  align-items:end; gap:4px 8px;
  min-width:0;
}
.logic-index{
  grid-column:1 / -1;
  font-size:8.5px; font-weight:650; letter-spacing:.45px;
  color:rgba(139,151,255,.64);
}
.logic-mode h3{
  flex:none;
  font-size:14.5px; line-height:1.25; font-weight:650;
  color:rgba(255,255,255,.94);
}
.logic-question{
  margin-left:0;
  padding:3px 7px;
  border:1px solid rgba(139,151,255,.16);
  border-radius:999px;
  background:rgba(139,151,255,.08);
  font-size:9px; line-height:1.2; font-weight:600;
  color:rgba(174,182,255,.72);
  white-space:nowrap;
}
.logic-copy,
.logic-note,
.logic-mode li{
  font-size:11.5px; line-height:1.5;
  color:rgba(255,255,255,.56);
}
.logic-copy{ margin-top:7px; color:rgba(255,255,255,.42); }
.logic-mode ul{
  display:grid; grid-template-columns:1fr 1fr; gap:2px 12px;
  margin-top:4px;
  list-style:none;
}
.logic-mode li:last-child{ grid-column:1 / -1; }
.logic-mode li{
  position:relative;
  padding-left:10px;
}
.logic-mode li::before{
  content:"";
  position:absolute; left:0; top:.68em;
  width:3px; height:3px; border-radius:50%;
  background:rgba(174,182,255,.66);
}
.logic-note{
  margin-top:6px;
  color:rgba(255,255,255,.42);
}
.logic-or{
  display:flex; align-items:center; gap:8px;
  margin:15px 0;
}
.logic-or::before,
.logic-or::after{
  content:"";
  height:1px; flex:1;
  background:rgba(255,255,255,.065);
}
.logic-or span{
  font-size:9.5px; line-height:1;
  color:rgba(255,255,255,.32);
}
@media (max-width: 1100px){
  .stage{ flex-direction:column-reverse; gap:32px; padding:24px 16px; }
  .intro{ width:520px; max-width:100%; }
}

.phone{
  position:absolute; left:0; top:0;
  width:414px; height:868px;
  border-radius:56px; padding:12px;
  background:linear-gradient(160deg,#2a2c31,#141519 42%,#26282d);
  box-shadow:
    0 2px 0 rgba(255,255,255,.08) inset,
    0 40px 90px -20px rgba(0,0,0,.85),
    0 0 0 1px rgba(0,0,0,.6);
  transform-origin:top left;
}
.screen{
  position:relative; width:390px; height:844px;
  border-radius:44px;
  overflow:hidden; /* 兼容不支持 overflow:clip 的旧浏览器 */
  overflow:clip;   /* 只裁切，不把手机屏幕变成可被 scrollIntoView 推动的滚动容器 */
  background:#3b4536; isolation:isolate;
}

/* ---------- 视频色延展背景 ---------- */
/* ---------- 直播间底图（真实截图，base64 内嵌，见文件末尾 --bg-photo） ---------- */
.live-photo{
  position:absolute; inset:0; z-index:0;
  background-image:var(--bg-photo);
  background-size:cover;
  background-position:top center;
  background-repeat:no-repeat;
}
/* 图下半部空白区压一层暗渐变，让公屏白字清晰 */
.photo-fade{
  position:absolute; left:0; right:0; top:34%; bottom:0; z-index:1;
  background:linear-gradient(180deg,
    rgba(20,26,18,0) 0%,
    rgba(16,20,14,.32) 30%,
    rgba(12,15,11,.62) 100%);
  pointer-events:none;
}
.photo-close{
  position:absolute; top:52px; right:14px; z-index:8;
  width:30px; height:30px; border-radius:50%; cursor:pointer;
  border:none; background:transparent; color:transparent;
  font-family:inherit;
}

/* ---------- 状态栏 ---------- */
.statusbar{
  position:absolute; top:0; left:0; right:0; height:46px; z-index:8;
  display:flex; align-items:center; justify-content:space-between;
  padding:14px 28px 0;
  font-size:14px; font-weight:600; color:#fff;
}
.sb-right{ display:flex; align-items:center; gap:6px; }
.sb-sig{ display:flex; align-items:flex-end; gap:2px; height:11px; }
.sb-sig i{ width:3px; background:#fff; border-radius:1px; }
.sb-sig i:nth-child(1){ height:4px; }
.sb-sig i:nth-child(2){ height:6px; }
.sb-sig i:nth-child(3){ height:8px; }
.sb-sig i:nth-child(4){ height:11px; }
.sb-wifi{
  width:13px; height:10px; background:#fff;
  clip-path:polygon(50% 100%, 0 34%, 12% 22%, 50% 62%, 88% 22%, 100% 34%);
}
.sb-batt{
  position:relative; width:23px; height:11px;
  border:1px solid rgba(255,255,255,.55); border-radius:3px; padding:1.5px;
}
.sb-batt::after{
  content:""; position:absolute; right:-3px; top:3.5px;
  width:2px; height:4px; border-radius:0 1px 1px 0; background:rgba(255,255,255,.55);
}
.sb-batt b{ display:block; height:100%; width:88%; background:#fff; border-radius:1.5px; }

/* ---------- 主播条 ---------- */
.anchor-row{
  position:absolute; top:50px; left:10px; right:10px; z-index:7;
  display:flex; align-items:center; gap:7px;
}
.anchor{
  display:flex; align-items:center; gap:7px;
  padding:3px 3px 3px 3px;
  background:rgba(0,0,0,.28);
  border-radius:999px;
  min-width:0; flex:1;
}
.anchor-av{
  flex:none; width:30px; height:30px; border-radius:50%;
  background:linear-gradient(140deg,#c9563e,#8a3f6d);
  display:flex; align-items:center; justify-content:center;
  font-size:9px; font-weight:800; color:#fff; letter-spacing:-.3px;
}
.anchor-meta{ min-width:0; line-height:1.2; }
.anchor-name{
  font-size:12.5px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:112px;
}
.anchor-sub{ font-size:10px; color:rgba(255,255,255,.78); margin-top:1px; }
.follow{
  flex:none; border:none; cursor:pointer; font-family:inherit;
  background:var(--accent); color:#fff;
  font-size:12px; font-weight:600; padding:5px 12px; border-radius:999px;
}

.viewer-box{
  flex:none; display:flex; align-items:center; gap:5px;
  padding:3px 9px 3px 3px;
  background:rgba(0,0,0,.28); border-radius:999px;
}
.faces{ display:flex; }
.faces i{
  width:22px; height:22px; border-radius:50%;
  border:1.5px solid rgba(255,255,255,.85); margin-right:-8px;
}
.faces .f1{ background:linear-gradient(140deg,#e0a27a,#a86b4a); }
.faces .f2{ background:linear-gradient(140deg,#8fb0d9,#5a7fa8); }
.faces .f3{ background:linear-gradient(140deg,#c7a4d9,#8b6bab); margin-right:2px; }
.viewer-num{ font-size:12px; font-weight:600; font-variant-numeric:tabular-nums; }

.close-x{
  flex:none; width:28px; height:28px; border-radius:50%; cursor:pointer;
  border:none; background:none; color:rgba(255,255,255,.9);
  font-size:15px; line-height:1; font-family:inherit;
}

/* ---------- 主播条 + 直播间信息（整条图叠层） ----------
   原图 1572×144，比例 10.9:1。屏幕宽 390 → 图高约 35.7px。
   放在状态栏下方（top≈50），榜单行（top:88）上方。 */
.anchor-strip{
  position:absolute; top:44px; left:0; right:0; height:38px; z-index:7;
  background-image:var(--bg-anchor);
  background-size:100% auto;
  background-position:center top;
  background-repeat:no-repeat;
  pointer-events:none;
}

/* ---------- 榜单行 ---------- */
.rank-row{
  position:absolute; top:88px; left:10px; right:0; z-index:7;
  display:flex; align-items:center; gap:6px;
}
.chip{
  padding:4px 10px; border-radius:999px;
  background:rgba(0,0,0,.26);
  font-size:11px; color:rgba(255,255,255,.92); white-space:nowrap;
}
.chip-go{
  margin-left:auto;
  /* 贴到屏幕右边缘：右两角直角，左两角保持半圆 */
  border-radius:999px 0 0 999px;
  padding-right:12px;
}

/* ---------- 活动条 ---------- */
.promo-row{
  position:absolute; top:118px; left:10px; right:10px; z-index:7;
  display:flex; align-items:center; gap:8px;
}
/* 活动图片卡（价值1999钻 + 圆形图标），各带倒计时角标 */
.promo-imgs{ display:flex; align-items:center; gap:6px; }
.promo-card{
  position:relative;
  background-size:contain; background-repeat:no-repeat; background-position:center;
}
.promo-card--wide{
  width:96px; height:32px;
  background-image:var(--promo-wide);
}
.promo-card--sq{
  width:32px; height:32px;
  background-image:var(--promo-sq);
}
/* 倒计时角标：压在图片内部底边居中 */
/* 倒计时角标：贴图片底边 */
.pc-time{
  position:absolute; left:50%; bottom:0; transform:translateX(-50%);
  font-size:7px; color:#fff;
  background:rgba(0,0,0,.5); padding:0 3px; border-radius:4px;
  line-height:10px;
  font-variant-numeric:tabular-nums; white-space:nowrap;
  max-width:100%;
}
/* 宽图的倒计时对齐到左侧礼物图标下方（避开"价值1999钻"文字） */
.promo-card--wide .pc-time{ left:14px; transform:translateX(-50%); }

.promo-charge{
  margin-left:auto;
  width:88px; height:34px;
  background-image:var(--promo-charge);
  background-size:contain; background-repeat:no-repeat; background-position:center right;
}
/* ============================================================
   横屏比赛画面
   ============================================================ */
.game{
  position:absolute; top:156px; left:0; right:0; height:220px; z-index:6;
  overflow:hidden;
}
.game-bg{
  position:absolute; inset:0;
  background:
    radial-gradient(58% 78% at 20% 34%, #7ba053 0%, transparent 60%),
    radial-gradient(52% 72% at 82% 66%, #567b56 0%, transparent 58%),
    linear-gradient(165deg, #688a4b, #35482f);
}
/* 一条斜向的路 + 两侧草丛，给画面一点构图，不做炫技 */
.game-lane{
  position:absolute; inset:0; opacity:.55;
  background:
    linear-gradient(112deg, transparent 34%, rgba(196,206,150,.34) 40%,
                    rgba(196,206,150,.34) 52%, transparent 58%),
    radial-gradient(28% 40% at 8% 82%, rgba(24,44,26,.55) 0%, transparent 70%),
    radial-gradient(24% 34% at 92% 20%, rgba(24,44,26,.5) 0%, transparent 70%);
}
.game-grid{
  position:absolute; inset:0; opacity:.5;
  background-image:
    repeating-linear-gradient(0deg, rgba(0,0,0,.05) 0 1px, transparent 1px 3px);
}

.g-top{
  position:absolute; top:8px; left:50%; transform:translateX(-50%);
  display:flex; align-items:center; gap:12px;
  padding:5px 12px; border-radius:8px;
  background:rgba(8,12,6,.55);
}
.g-team{ display:flex; align-items:center; gap:7px; }
