/* ============================================================
   公屏
   样式与动效严格对齐 live-ai-summary 参考稿（Figma 还原值）
   ============================================================ */
.feed{
  --filter-scan-duration:1500ms;
  --filter-scan-total-duration:3000ms;
  position:absolute; left:0; right:0;
  top:520px; bottom:76px; z-index:6;
  overflow:hidden;
  isolation:isolate;
  /* 底部对齐的流式栈 */
  display:flex; flex-direction:column; justify-content:flex-end;
  transition:top .28s var(--ease), bottom .28s var(--ease);
}
.feed::before{
  content:"";
  position:absolute;
  inset:0 54px 0 12px;
  z-index:4;
  border-radius:15px;
  background:linear-gradient(
    110deg,
    transparent 32%,
    rgba(157,112,255,.19) 39%,
    rgba(83,181,255,.28) 46%,
    rgba(252,249,255,.27) 50%,
    rgba(157,112,255,.28) 55%,
    transparent 68%
  );
  background-size:240% 240%;
  background-repeat:no-repeat;
  /* 待机位置与扫描终点一致，避免 Safari 在隐藏前跳回右侧绘制一帧 */
  background-position:-180% -180%;
  filter:blur(6px);
  mix-blend-mode:screen;
  opacity:0;
  visibility:hidden;
  pointer-events:none;
  will-change:auto;
}
.feed.filter-scan-active::before{
  animation:filterGlareScan var(--filter-scan-duration) linear 2;
  visibility:visible;
  will-change:opacity,background-position;
}
.feed.filter-scan-active .feed-list{
  animation:filterScanBreathe var(--filter-scan-total-duration) linear both;
}
@keyframes filterGlareScan{
  0%{
    opacity:0;
    background-position:100% 100%;
  }
  10%{ opacity:1; }
  84%{ opacity:1; }
  92%{ opacity:0; }
  100%{
    opacity:0;
    background-position:-180% -180%;
  }
}
@keyframes filterScanBreathe{
  0%{ opacity:1; }
  8%{ opacity:.9; }
  21%{ opacity:.28; }
  37%{ opacity:.84; }
  46%{ opacity:1; }
  50%{ opacity:1; }
  58%{ opacity:.88; }
  70%{ opacity:.2; }
  78%{ opacity:.32; }
  90%{ opacity:.84; }
  100%{ opacity:1; }
}
.screen.filter-active:not(.filter-settings-open):not(.kb-open) .feed{
  top:411px;
}
/* 键盘升起时：键盘占屏幕下方（320px），评论区整体抬到键盘 + 输入面板上方 */
.screen.kb-open .feed{ top:258px; bottom:430px; }
.screen.filter-settings-open .feed{ top:258px; bottom:414px; }
.screen.filter-settings-open.topic-kb-open .feed{
  top:132px;
  bottom:590px;
}

/* 键盘升起时：顶部主播条 / 榜单 / 活动条 / 关闭按钮 一起隐藏，键盘收起才恢复 */
.anchor-strip,
.rank-row,
.promo-row,
.photo-close{
  transition:opacity .18s var(--ease), transform .22s var(--ease);
}
.screen.kb-open .anchor-strip,
.screen.kb-open .rank-row,
.screen.kb-open .promo-row,
.screen.kb-open .photo-close,
.screen.filter-settings-open .anchor-strip,
.screen.filter-settings-open .rank-row,
.screen.filter-settings-open .promo-row,
.screen.filter-settings-open .photo-close{
  opacity:0;
  transform:translateY(-6px);
  pointer-events:none;
}

/* 进场横幅：独立层，固定在礼物区上方的空白带（游戏画面下方） */
.join-banner{
  position:absolute; left:12px; z-index:11;
  top:381px;                   /* 游戏画面下方、礼物区之上的空白带（较原位上移 25px） */
  width:184px; height:26px;
  background-image:var(--join);
  background-size:contain; background-repeat:no-repeat; background-position:left center;
  opacity:0; pointer-events:none;
  transform:translateX(360px);
  will-change:transform, opacity;
}
.join-banner.is-play{ animation:joinFlow 4.4s forwards; }
.screen.filter-active .join-banner{
  opacity:0 !important;
  visibility:hidden;
  animation:none !important;
  pointer-events:none;
}
@keyframes joinFlow{
  /* 1) 右侧快速平入到停留位（先快后稳，减速到位） */
  0%   { transform:translateX(360px); opacity:0; animation-timing-function:cubic-bezier(.16,.8,.3,1); }
  6%   { opacity:1; }
  30%  { transform:translateX(0);     opacity:1; animation-timing-function:linear; }
  /* 2) 停留（几乎不动，匀速微移，出停留时速度≈0，自然衔接下一段加速） */
  66%  { transform:translateX(-4px);  opacity:1; animation-timing-function:cubic-bezier(.7,0,.84,0); }
  /* 3+4) 一条连续的 ease-in 加速直接冲出——速度单调递增，无骤停 */
  97%  { opacity:1; }
  100% { transform:translateX(-640px); opacity:0; }
}
/* 送礼区：独立层，位于进场横幅下方、评论区上方（键盘升起时不跟评论区一起动） */
.gift-area{
  position:absolute; left:0; right:0;
  top:411px;                    /* 紧贴 join-banner 下沿（381+26=407）+4 缓冲 */
  height:105px;                 /* 容纳两条堆叠礼物条 */
  z-index:5;
  display:flex; flex-direction:column;
  align-items:flex-start; justify-content:flex-end;
  gap:4px; overflow:hidden;
  padding:0 54px 4px 12px;
  pointer-events:none;
  transition:opacity .18s linear, transform .22s var(--ease);
}
.screen.filter-active .gift-area{
  opacity:0;
  transform:translateY(-6px);
}
/* 评论区：贴最底部，紧邻输入框 */
.feed-list{
  position:relative;
  display:flex; flex-direction:column;
  justify-content:flex-end; align-items:flex-start;
  gap:4px; overflow:hidden;
  padding:0 54px 0 12px;
  height:100%;
  overscroll-behavior:contain;
  touch-action:pan-y;
  scrollbar-width:none;
  -ms-overflow-style:none;
  /* 顶部渐变 mask：评论滚出的地方自然淡出 */
  -webkit-mask-image:linear-gradient(to bottom, transparent 0%, black 32px);
          mask-image:linear-gradient(to bottom, transparent 0%, black 32px);
}
.feed-list.is-history-browsing{
  justify-content:flex-start;
  overflow-x:hidden;
  overflow-y:auto;
  -webkit-overflow-scrolling:touch;
}
.feed-list::-webkit-scrollbar{ width:0; height:0; }
.feed-list.is-history-browsing > .sizer:first-child{ margin-top:auto; }

/* 入场：外层 sizer 的 max-height 从 0 线性长到 100px，
   把上面的消息平滑顶上去（恒定 200px/s，与内容高度无关） */
.sizer{
  max-height:0; overflow:visible;
  max-width:100%;
  /* 参考稿原速：0.5s 线性长到 100px（恒定 200px/s） */
  transition:max-height .5s linear;
}
.sizer.is-filter-removing{
  overflow:visible;
  pointer-events:none;
}
.sizer.is-live-entering > *{
  animation:douyinCommentEnter .34s cubic-bezier(.22,1,.36,1) both;
}
@keyframes douyinCommentEnter{
  from{ opacity:.14; transform:translateY(2px); }
  to{ opacity:1; transform:translateY(0); }
}

