/* 自己发的评论在原公屏结构内持续高亮，样式定义见筛选控件区。 */

/* ============================================================
   右侧动态体验引导层 Try the demo
   ============================================================ */
.guide{
  width:280px; max-width:88vw;
  align-self:stretch;
  display:flex; flex-direction:column;
  gap:18px;
  padding:26px 22px;
  border-radius:20px;
  background:rgba(255,255,255,.03);
  border:1px solid rgba(255,255,255,.07);
  box-shadow:0 24px 60px -30px rgba(0,0,0,.9);
  color:#fff;
  align-self:center;
}
.guide-head{
  display:flex; align-items:center; justify-content:space-between;
}
.guide-kicker{
  font-size:12px; font-weight:600; letter-spacing:1.4px;
  text-transform:uppercase;
  color:var(--accent-2, #7c8cff);
}
.guide-progress{
  display:flex; align-items:baseline; gap:3px;
  font-variant-numeric:tabular-nums;
}
.gp-cur{ font-size:20px; font-weight:700; color:#fff; }
.gp-sep{ font-size:13px; color:rgba(255,255,255,.35); }
.gp-total{ font-size:13px; color:rgba(255,255,255,.4); }

/* 进度条 */
.guide-track{
  height:3px; border-radius:99px;
  background:rgba(255,255,255,.08);
  overflow:hidden;
}
.guide-bar{
  height:100%; width:20%;
  border-radius:99px;
  background:linear-gradient(90deg, var(--accent-2, #7c8cff), #9aa6ff);
  transition:width .45s cubic-bezier(0.22, 1, 0.36, 1);
}

/* 当前步卡片：每次只显示一步，切换时淡入上移 */
.guide-card{
  min-height:132px;
  display:flex; flex-direction:column; gap:10px;
}
.guide-title{
  font-size:17px; font-weight:650; line-height:1.3;
  color:#fff;
}
.guide-desc{
  font-size:13.5px; line-height:1.6;
  color:rgba(255,255,255,.62);
}
.guide-hintline{
  margin-top:2px;
  font-size:12.5px; line-height:1.5;
  color:var(--accent-2, #7c8cff);
  display:flex; align-items:center; gap:6px;
}
.guide-hintline:empty{ display:none; }
.guide-hintline::before{
  content:"›"; font-size:15px; line-height:1; flex:none;
  opacity:.9;
}
/* 步骤切换动画：JS 加 .is-swap 触发 */
.guide-card.is-swap .guide-title,
.guide-card.is-swap .guide-desc,
.guide-card.is-swap .guide-hintline{
  animation:guideIn .42s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.guide-card.is-swap .guide-desc{ animation-delay:.05s; }
.guide-card.is-swap .guide-hintline{ animation-delay:.1s; }
@keyframes guideIn{
  from{ opacity:0; transform:translateY(8px); }
  to  { opacity:1; transform:translateY(0); }
}

/* 完成态 */
.guide-done{
  display:flex; align-items:center; gap:9px;
  padding:12px 14px;
  border-radius:12px;
  background:rgba(124,140,255,.12);
  border:1px solid rgba(124,140,255,.28);
  animation:guideIn .42s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.guide-done[hidden]{ display:none; }   /* 未完成前必须隐藏（display:flex 会覆盖原生 hidden） */
.gd-check{
  flex:none; width:22px; height:22px; border-radius:50%;
  display:flex; align-items:center; justify-content:center;
  background:var(--accent-2, #7c8cff); color:#fff;
  font-size:13px; font-weight:700;
}
.gd-text{ font-size:14px; font-weight:600; color:#fff; }

/* Restart */
.guide-restart{
  margin-top:auto;
  align-self:flex-start;
  display:inline-flex; align-items:center; gap:7px;
  padding:8px 14px;
  border-radius:99px;
  border:1px solid rgba(255,255,255,.14);
  background:rgba(255,255,255,.04);
  color:rgba(255,255,255,.7);
  font-family:inherit; font-size:12.5px; font-weight:500;
  cursor:pointer;
  transition:background .18s linear, color .18s linear, border-color .18s linear;
}
.guide-restart:hover{
  background:rgba(255,255,255,.08);
  color:#fff; border-color:rgba(255,255,255,.24);
}
.gr-ico{ font-size:14px; line-height:1; }

@media (max-width:1180px){
  .guide,.step-pointer{ display:none; }   /* 窄屏优先保证手机原型可用 */
}

/* 14 寸笔记本常见浏览器高度约 760–900px。
   通过承载层同步缩小布局占位，避免仅做 transform 后仍被页面裁切。 */
@media (max-height:940px) and (min-width:1101px){
  .stage{ padding:20px; gap:44px; }
  .phone-frame{ width:364.32px; height:763.84px; }
  .phone{ transform:scale(.88); }
  .intro{ width:380px; gap:14px; }
  .guide{ width:260px; padding:22px 18px; gap:16px; }
}

@media (max-height:840px) and (min-width:1101px){
  .stage{ padding:16px; gap:36px; }
  .phone-frame{ width:339.48px; height:711.76px; }
  .phone{ transform:scale(.82); }
  .intro{ width:360px; gap:14px; }
  .intro-context-row{ padding:10px 0; }
  .guide{ width:250px; padding:20px 18px; gap:14px; }
  .guide-card{ min-height:116px; }
}

@media (max-height:760px) and (min-width:1101px){
  .stage{ padding:12px; gap:30px; }
  .phone-frame{ width:306.36px; height:642.32px; }
  .phone{ transform:scale(.74); }
  .intro{ width:330px; gap:12px; }
  .intro-thesis{ font-size:16.5px; line-height:1.48; }
  .intro-context{ margin-top:0; }
  .intro-context-row{ padding:8px 0; }
  .intro-context dd{ font-size:12px; line-height:1.55; }
  .intro-idea{ margin-top:15px; }
  .intro-idea h2{ margin-top:6px; font-size:15px; }
  .intro-idea p{ margin-top:6px; font-size:12px; line-height:1.55; }
  .intro-metrics{ margin-top:10px; padding-top:9px; }
  .intro-metrics-list{ gap:12px; margin-top:11px; }
  .intro-metric + .intro-metric{ padding-left:11px; }
  .logic-head h2{ font-size:17px; }
  .logic-flow{ margin-top:14px; }
