/* ============================================================
   底部操作条
   ============================================================ */
.dock{
  position:absolute; left:0; right:0; bottom:26px; z-index:20;
  height:44px; padding:0 12px;
  transition:transform .34s var(--ease), opacity .22s linear,
             bottom .28s var(--ease), height .28s var(--ease),
             background-color .2s linear;
}
/* 键盘升起时：dock 抬到键盘顶部，且整体变高（含输入框行 + 工具行） */
.screen.kb-open .dock{
  bottom:320px;
  height:110px;
  padding:0;
  left:0; right:0;
  background:#ffffff;                        /* 与参考稿一致：纯白输入面板 */
  box-shadow:0 -1px 0 rgba(0,0,0,.05);
}

.dock-normal,
.dock-typing{
  position:absolute; inset:0 12px;
  display:flex; align-items:center; gap:8px;
  transition:opacity .18s linear;
}
.dock-typing{
  opacity:0; pointer-events:none;
  flex-direction:column; align-items:stretch;
  inset:0;                                  /* 撑满 dock，白色面板 */
  padding:10px 0 0;
  gap:8px;
}
.dock.is-typing .dock-normal{ opacity:0; pointer-events:none; }
.dock.is-typing .dock-typing{ opacity:1; pointer-events:auto; }
.screen.topic-kb-open .dock{
  opacity:0;
  pointer-events:none;
  transform:translateY(10px);
}

/* 输入框行 */
.typing-input-row{
  display:flex; align-items:center; gap:8px;
  width:100%;
  padding:0 14px;
}
.live-input-wrap{
  flex:1; min-width:0; height:40px;
  display:flex; align-items:center;
  padding:0 14px;
  background:#f2f2f7;
  border-radius:999px;
}
.live-input{
  flex:1; min-width:0; height:100%;
  border:none; background:transparent;
  color:#0a0a0a; font-size:16px; font-family:inherit; outline:none;
  padding:0;
  /* 只保留一个红色光标（原生 caret），随打字自然推进 */
  caret-color:#ff2442;
}
.live-input::placeholder{ color:#8e8e93; }
.live-send{
  flex:none; height:40px; padding:0 18px; cursor:pointer;
  border:none; border-radius:999px; font-family:inherit;
  font-size:14px; font-weight:600;
  background:rgba(0,0,0,.06); color:rgba(0,0,0,.32);
  transition:background .16s linear, color .16s linear, opacity .16s linear;
  opacity:0; width:0; padding:0; overflow:hidden;   /* 无内容时收起，避免抢占宽度 */
}
.dock.is-typing .live-send{
  opacity:1; width:auto; padding:0 18px;
}
.live-send.is-ready{ background:var(--accent); color:#fff; }

/* 工具行：左侧表情快捷 + 右侧图标 */
.typing-tools{
  width:100%;
  height:52px;
  overflow:hidden;
  flex:none;
  background:#fff;
}
.typing-tools-img{
  display:block;
  width:100%;
  height:59px;
  object-fit:fill;
  object-position:top center;
}
.tt-left, .tt-right{
  display:flex; align-items:center; gap:16px;
}
.tt-right{ margin-left:auto; }
.tt-emoji{
  font-size:22px; line-height:1;
  cursor:pointer;
  user-select:none;
}
/* 徽标式表情：右上角红色 "互粉" 标 */
.tt-emoji--badge{
  position:relative;
  display:inline-block;
  font-size:22px; line-height:1;
  min-width:auto; height:auto; padding:0;
  background:transparent; color:inherit;
  border-radius:0; font-weight:400;
}
.tt-emoji--badge::after{
  content:"互粉";
  position:absolute; left:-6px; top:-4px;
  background:#ff2442; color:#fff;
  font-size:9px; font-weight:600;
  padding:1px 4px; border-radius:6px;
  line-height:1.1; letter-spacing:.5px;
  font-family:"PingFang SC",-apple-system,sans-serif;
}
.tt-ico{
  width:24px; height:24px; cursor:pointer;
  display:inline-flex; align-items:center; justify-content:center;
  color:#3c3c43;
}
.tt-ico svg{
  width:22px; height:22px;
  stroke:currentColor; fill:none; stroke-width:1.6;
}
.tt-divider{
  width:1px; height:18px;
  background:#e5e5ea;
}

/* ─── 模拟系统键盘（对齐 keyboard-panel 参考稿） ─── */
.keyboard{
  position:absolute; left:0; right:0; bottom:0; z-index:19;
  height:320px;                 /* 再 +10px */
  background:#d1d3d9;
  padding:0;
  transform:translateY(100%);
  visibility:hidden;
  transition:transform .28s var(--ease), visibility 0s linear .28s;
  will-change:transform;
  user-select:none;
}
.screen.kb-open .keyboard{
  transform:translateY(0);
  visibility:visible;
  transition-delay:0s;
}
.screen.topic-kb-open .keyboard{
  transform:translateY(0);
  visibility:visible;
  transition-delay:0s;
}

/* 候选词栏 */
.kb-suggest{
  display:flex; align-items:center;
  height:38px;
  padding:0 12px;
  background:#d1d3d9;
  font-size:17px; color:#000; font-weight:400;
  overflow:hidden;
  position:relative;
}
.kb-suggest-list{
  flex:1; min-width:0;
  display:flex; align-items:center; gap:22px;
  overflow:hidden;
  white-space:nowrap;
}
.kb-suggest-list span{
  flex:none;
}
.kb-suggest-list span:first-child{ color:#000; font-weight:500; }
.kb-suggest-more{
  flex:none;
  padding-left:10px;
  color:#5a5a5e;
  font-size:16px;
  position:relative;
}
.kb-suggest-more::before{
  content:""; position:absolute; left:-16px; top:0; bottom:0; width:16px;
  background:linear-gradient(to right, rgba(209,211,217,0), rgba(209,211,217,1));
  pointer-events:none;
}

/* 按键区 */
.kb-rows{
  display:flex; flex-direction:column;
  gap:10px;
  padding:8px 3px 6px;
}
.kb-row{
  display:flex; gap:6px; justify-content:center;
}
/* 第二行左右缩进半个键 */
.kb-row.kb-row-indent{ padding:0 20px; }

.kb-row i{
  flex:1; height:42px;
  display:flex; align-items:center; justify-content:center;
  background:#ffffff;
  border-radius:5px;
  box-shadow:0 1px 0 rgba(0,0,0,.28);
  font-style:normal; font-size:22px; font-weight:400;
  color:#000;
}
.kb-row i.kb-fn{
  background:#adb3bc;
  color:#000;
  font-size:15px;
}
.kb-row i.kb-fn-wide{ flex:1.5; }
.kb-row i.kb-fn-w{ flex:1.5; font-size:15px; }
.kb-row i.kb-space{
  flex:5;
  background:#ffffff;
  font-size:15px; color:#000;
}
.kb-row i.kb-return{
  background:#007aff;
  color:#fff;
  font-size:16px; font-weight:600;
}
.kb-row-last{ gap:6px; }
.kb-row-last i{ height:42px; }

.dock-input{
  flex:1; min-width:0; height:38px; cursor:pointer;
  display:flex; align-items:center; justify-content:space-between; gap:6px;
  padding:0 12px 0 15px;
  border-radius:999px; border:none;
  background:rgba(0,0,0,.3);
  color:rgba(255,255,255,.72); font-size:13.5px; font-family:inherit;
}
.di-emoji{ font-style:normal; font-size:16px; color:rgba(255,255,255,.72); }
.di-emoji.has-img{
  display:inline-block;
  width:22px; height:22px;
  background-image:var(--ico-face);
  background-repeat:no-repeat;
  background-position:center center;
  background-size:contain;
  color:transparent;
  opacity:.85; /* 与原字符 .72 相近但稍亮 */
}

.dock-ico{
  flex:none; width:38px; height:38px; border-radius:50%; cursor:pointer;
  border:none; background:rgba(0,0,0,.3);
  color:#fff; font-size:17px; font-family:inherit;
  display:flex; align-items:center; justify-content:center;
}
.dock-share{ font-size:19px; }

/* 图片版按钮：隐藏文字/emoji，用背景图代替 */
.dock-ico.has-img{
  color:transparent;
  background-repeat:no-repeat;
  background-position:center center;
  /* 背景色沿用 rgba(0,0,0,.3) 底 */
}
.dock-ico.ico-heart{
  background-image:var(--ico-heart),
                   linear-gradient(rgba(0,0,0,.3),rgba(0,0,0,.3));
  background-size:26px auto, cover;
  background-position:center, center;
  background-repeat:no-repeat, no-repeat;
}
.dock-ico.ico-gift{
  background-image:var(--ico-gift),
                   linear-gradient(rgba(0,0,0,.3),rgba(0,0,0,.3));
  background-size:24px auto, cover;
  background-position:center, center;
  background-repeat:no-repeat, no-repeat;
}
.dock-ico.ico-share{
  background-image:var(--ico-share),
                   linear-gradient(rgba(0,0,0,.3),rgba(0,0,0,.3));
  background-size:20px auto, cover;
  background-position:center, center;
  background-repeat:no-repeat, no-repeat;
}

.home-bar{
  position:absolute; left:50%; bottom:9px; transform:translateX(-50%);
  width:134px; height:5px; border-radius:3px;
  background:rgba(255,255,255,.85); z-index:40;
}

/* ============================================================
   遮罩 + 分享 / 更多面板
   ============================================================ */
.scrim{
  position:absolute; inset:0; z-index:27;
  background:rgba(0,0,0,.45);
  opacity:0; pointer-events:none;
  transition:opacity .28s linear;
}
.screen.more-open .scrim{ opacity:1; pointer-events:auto; }

.more-sheet{
  position:absolute; left:0; right:0; bottom:0; z-index:28;
  padding:0 0 26px;
  background:#f4f5f7;
  color:#0a0a0a;
  border-radius:18px 18px 0 0;
  /* 完全移出屏幕下方：102% 在部分视口下仍会露出底部一条，改用 120% + 兜底位移 */
  transform:translateY(120%);
  visibility:hidden;
  transition:transform .34s var(--ease-sheet), visibility 0s linear .34s;
}
.screen.more-open .more-sheet{
  transform:translateY(0);
  visibility:visible;
  transition-delay:0s;
}
/* 隐藏时彻底不可交互，杜绝残留露出条被点到 */
.more-sheet[aria-hidden="true"]{ pointer-events:none; }
.screen.more-open .more-sheet{ pointer-events:auto; }

.more-sheet .sheet-grab{ padding-top:8px; padding-bottom:6px; }
.more-sheet .sheet-grab span{ background:rgba(0,0,0,.14); }

/* 顶部大标题 */
.ms-title{
  font-size:16px; font-weight:600;
  padding:12px 20px 14px;
  color:#0a0a0a;
}

/* 顶部：分享给谁 */
.ms-share-row{
  display:flex; gap:22px;
  padding:0 20px 22px;
}
.ms-friend{
  width:56px; cursor:pointer;
  display:flex; flex-direction:column; align-items:center; gap:6px;
  border:0; background:none; font-family:inherit; padding:0;
}
.msf-av{
  width:56px; height:56px; border-radius:50%;
  background:linear-gradient(140deg,#f2c9d1,#c98094);
  flex:none;
}
.ms-more .msf-av{
  background:#fff;
  display:flex; align-items:center; justify-content:center;
  color:#666; font-size:26px; font-weight:400; line-height:1;
}
.msf-more-ico{ padding-bottom:4px; }
.msf-name{
  font-size:13px; color:#0a0a0a; font-weight:500;
  margin-top:2px;
}
.msf-sub{
  font-size:11px; color:#999;
}

/* 推广条 */
.ms-promo{
  display:flex; align-items:center; gap:10px;
  margin:0 16px 22px;
  padding:12px 14px;
  background:#fff;
  border-radius:12px;
  font-size:13px;
}
.ms-promo-ico{
  width:22px; height:22px; border-radius:6px;
  background:#000;
  color:#fff; font-weight:900; font-style:italic;
  display:inline-flex; align-items:center; justify-content:center;
  font-size:14px; flex:none;
}
.ms-promo-text{ color:#0a0a0a; }
.ms-promo-text b{ color:#3a7cff; font-weight:500; }

/* 功能网格：5 列 */
.ms-grid{
  display:grid; grid-template-columns:repeat(5, 1fr);
  gap:18px 0;
  padding:0 8px;
}
:root{
  --msi-save:url("data:image/webp;base64,");
  --msi-link:url("data:image/webp;base64,");
  --msi-chat:url("data:image/webp;base64,");
  --msi-hot:url("data:image/webp;base64,");
  --msi-clear:url("data:image/webp;base64,");
  --msi-quality:url("data:image/webp;base64,");
  --msi-settings:url("data:image/webp;base64,");
  --msi-report:url("data:image/webp;base64,");
  --msi-dislike:url("data:image/webp;base64,");
}
.ms-item{
  cursor:pointer;
  display:flex; flex-direction:column; align-items:center; gap:8px;
  border:0; background:none; font-family:inherit; padding:6px 0;
  font-size:12px; color:#0a0a0a;
}
.msi-ico{
  width:46px; height:46px; border-radius:50%;
  background:#fff center/100% 100% no-repeat;
  display:flex; align-items:center; justify-content:center;
  font-size:0; font-style:normal; color:transparent;
  transition:transform .16s var(--ease);
}
.msi-save{ background-image:var(--msi-save); }
.msi-link{ background-image:var(--msi-link); }
.msi-chat{ background-image:var(--msi-chat); }
.msi-hot{ background-image:var(--msi-hot); }
.msi-clear{ background-image:var(--msi-clear); }
.msi-quality{ background-image:var(--msi-quality); }
.msi-settings{ background-image:var(--msi-settings); }
.msi-report{ background-image:var(--msi-report); }
.msi-dislike{ background-image:var(--msi-dislike); }
.ms-item:active .msi-ico{ transform:scale(.92); }

/* ============================================================
   智能评论筛选
   ============================================================ */
.dock-filter img{
  width:28px; height:28px;
  display:block;
  object-fit:contain;
}
.filter-tip{
  position:absolute; left:12px; bottom:48px; z-index:24;
  height:30px; padding:0 10px;
  border:0; border-radius:8px;
  background:rgba(255,255,255,.96);
  color:#222; font:inherit; font-size:12px; font-weight:600;
  box-shadow:0 8px 18px rgba(0,0,0,.22);
  opacity:0; transform:translateY(6px);
  pointer-events:none;
  transition:opacity .2s linear, transform .24s var(--ease);
}
.filter-tip::after{
  content:""; position:absolute; left:16px; bottom:-5px;
  width:10px; height:10px; transform:rotate(45deg);
  background:rgba(255,255,255,.96);
}
.filter-tip.is-on{
  opacity:1; transform:translateY(0); pointer-events:auto;
}
.dock.is-typing .filter-tip,
.screen.filter-settings-open .filter-tip{
  opacity:0; pointer-events:none;
}
.dock-filter:focus-visible,.filter-tip:focus-visible,
.filter-row-main:focus-visible,.filter-switch:focus-visible,
.filter-info-button:focus-visible,.topic-input-wrap button:focus-visible{
  outline:2px solid rgba(124,140,255,.9); outline-offset:2px;
}
.msg-plain.is-mine{
  background:
    linear-gradient(
      105deg,
      transparent 22%,
      rgba(255,55,92,.055) 36%,
      rgba(255,37,92,.30) 50%,
      rgba(255,37,124,.09) 64%,
      transparent 78%
    ) 130% 0 / 190% 100% no-repeat,
    linear-gradient(90deg, rgba(255,37,124,.3), rgba(255,37,124,0)) 0 0 / 100% 100% no-repeat,
    rgba(0,0,0,.45);
  border:0;
  animation:mineCommentGradientReveal 3.4s linear both;
}
.sizer.is-live-entering > .msg-plain.is-mine{
  animation:
    douyinCommentEnter .28s cubic-bezier(.22,1,.36,1) both,
    mineCommentGradientReveal 3.4s linear both;
}
@keyframes mineCommentGradientReveal{
  0%{
    background-position:130% 0, 0 0;
    box-shadow:inset 0 0 0 rgba(255,37,92,0), 0 0 0 rgba(255,37,92,0);
  }
  24%{
    box-shadow:inset 0 0 14px rgba(255,37,92,.022), 0 0 14px rgba(255,37,92,.048);
  }
  56%{
    box-shadow:inset 0 0 18px rgba(255,37,92,.032), 0 0 18px rgba(255,37,92,.066);
  }
  82%{
    box-shadow:inset 0 0 10px rgba(255,37,92,.014), 0 0 10px rgba(255,37,92,.03);
  }
  100%{
    background-position:-130% 0, 0 0;
    box-shadow:inset 0 0 0 rgba(255,37,92,0), 0 0 0 rgba(255,37,92,0);
  }
}
.msg-plain.is-mine .uname{ color:#fff; font-weight:500; }
.msg-plain.is-mention .body{ color:#fff; }
.msg-plain.is-mention .mention-me{ color:#8CE7FF; }
.msg-plain.is-filtering-out{
  opacity:0;
  transition:opacity .42s linear;
}
.filter-scrim{
  position:absolute; inset:0; z-index:29;
  background:transparent; opacity:0; pointer-events:none;
  transition:opacity .26s linear;
}
.screen.filter-settings-open .filter-scrim{ opacity:0; pointer-events:none; }
.filter-sheet{
  position:absolute; left:0; right:0; bottom:0; z-index:30;
  height:414px; background:var(--surface); color:var(--txt);
  border-radius:20px 20px 0 0; border:0;
  box-shadow:0 -18px 44px -12px rgba(0,0,0,.7);
  transform:translateY(110%); visibility:hidden;
  transition:transform .36s var(--ease-sheet), bottom .28s var(--ease), height .24s var(--ease), visibility 0s linear .36s;
}
.screen.filter-settings-open .filter-sheet{
  transform:translateY(0); visibility:visible; transition-delay:0s;
}
.screen.topic-kb-open .filter-sheet{
  bottom:320px;
  height:258px;
}
.filter-sheet[aria-hidden="true"]{ pointer-events:none; }
.filter-sheet-grab{ display:none; }
.filter-sheet-grab span{ width:36px; height:4px; border-radius:2px; background:rgba(255,255,255,.22); }
.filter-sheet-body{
  height:100%;
  padding:20px 0 0;
  overflow:hidden;
  display:flex;
  flex-direction:column;
}
.filter-sheet-title{
  display:flex; align-items:center; gap:8px;
  flex:none;
  margin:0;
  padding:0 12px 16px;
  border-bottom:1px solid rgba(255,255,255,.08);
  font-size:17px; font-weight:650; line-height:1.35;
}
.filter-title-icon{
  width:18px; height:18px; display:inline-flex; align-items:center; justify-content:center;
}
.filter-title-icon img{
  width:18px; height:18px;
  display:block;
  object-fit:contain;
}
.filter-scroll{
  flex:1;
  min-height:0;
  padding:0 12px 24px;
  overflow-y:auto;
  overscroll-behavior:contain;
  scrollbar-width:none;
  -ms-overflow-style:none;
}
.filter-scroll::-webkit-scrollbar{ width:0; height:0; }
.filter-section{ margin-top:22px; }
.filter-label{
  display:block; margin-bottom:9px;
  color:var(--txt-3); font-size:11.5px; font-weight:550;
}
.filter-card{
  border-radius:7px;
  background:rgba(255,255,255,.06);
  overflow:hidden;
}
.filter-row{
  min-height:40px; padding:0 12px;
  display:flex; align-items:center; gap:8px;
}
.filter-row-label{
  flex:1; min-width:0;
  display:flex; align-items:center; justify-content:flex-start; gap:4px;
}
.filter-row-main{
  flex:none; min-width:0; height:40px; padding:0;
  border:0; background:transparent; color:rgba(255,255,255,.78);
  font:inherit; font-size:13px; text-align:left; cursor:pointer;
}
.filter-row-main.is-active{ color:#fff; }
.filter-info-button{
  flex:none; width:16px; height:16px;
  border:1px solid rgba(255,255,255,.32);
  border-radius:50%; background:transparent;
  color:rgba(255,255,255,.54);
  font:inherit; font-size:10px; line-height:1; cursor:pointer;
}
.filter-info-button:disabled{ opacity:.55; cursor:default; }
.filter-switch{
  flex:none; width:34px; height:20px; padding:0 2px;
  border:0; border-radius:999px; background:rgba(255,255,255,.34);
  display:flex; align-items:center; cursor:pointer;
  transition:background .18s linear;
}
.filter-switch span{
  width:16px; height:16px; border-radius:50%; background:#f7f7f9;
  transform:translateX(0);
  transition:transform .18s var(--ease);
}
.filter-switch.is-on{ background:var(--accent); }
.filter-switch.is-on span{ transform:translateX(14px); }
.filter-desc{
  margin:8px 0 0; padding:12px;
  border-radius:7px;
  background:rgba(255,255,255,.06);
  color:var(--txt-2); font-size:12px; line-height:1.55;
}
.filter-topic-area{
  padding:0 12px 12px;
  border-top:1px solid rgba(255,255,255,.07);
  transition:opacity .18s linear;
}
.filter-topic-area.is-disabled{
  opacity:.38;
  pointer-events:none;
}
.filter-sub-label{
  display:block; margin:12px 0 9px;
  color:var(--txt-3); font-size:11.5px;
}
.topic-list{ display:flex; flex-wrap:wrap; gap:8px; min-height:29px; }
.topic-chip{
  height:24px; padding:0 7px 0 10px;
  display:inline-flex; align-items:center; gap:6px; border-radius:4px;
  background:rgba(255,255,255,.08);
  color:rgba(255,255,255,.74); font-size:11.5px;
}
.topic-chip button{
  width:auto; height:auto; padding:0; border:0; border-radius:0;
  background:transparent; color:rgba(255,255,255,.5);
  font:inherit; line-height:1; cursor:pointer;
}
.topic-input-wrap{
  position:relative;
  height:36px; margin-top:12px; padding:0;
  display:flex; align-items:center; gap:8px; border-radius:5px;
  background:transparent;
}
.topic-input-wrap input{
  position:relative; z-index:1;
  flex:1; min-width:0; height:36px; border:0; outline:0;
  padding:0 12px 0 18px; border-radius:5px;
  background:rgba(255,255,255,.06);
  color:var(--txt); font:inherit; font-size:12px;
  caret-color:var(--accent);
  -webkit-appearance:none;
  appearance:none;
}
.topic-input-wrap input:focus{ outline:0; box-shadow:none; }
.topic-input-wrap input::placeholder{ color:var(--txt-3); }
.topic-input-wrap button{
  align-self:stretch; width:46px; margin-left:0; border:0; border-radius:5px;
  background:var(--accent); color:#fff;
  font:inherit; font-size:12px; font-weight:650; cursor:pointer;
}
.topic-input-wrap button:disabled{
  background:rgba(255,255,255,.12);
  color:rgba(255,255,255,.4);
}
.toast{
  position:absolute; left:50%; bottom:86px; z-index:42;
  max-width:calc(100% - 32px); padding:7px 13px; border-radius:999px;
  background:rgba(8,10,12,.9); border:1px solid rgba(255,255,255,.1);
  color:rgba(255,255,255,.9); font-size:12px; white-space:nowrap;
  opacity:0; transform:translate(-50%,6px); pointer-events:none;
  transition:opacity .2s linear, transform .24s cubic-bezier(.22,1,.36,1);
}
.toast.is-on{ opacity:1; transform:translate(-50%,0); }
@media (prefers-reduced-motion:reduce){
  .filter-tip,.filter-switch,.filter-switch span,
  .msg-plain.is-filtering-out,.filter-sheet{ transition-duration:.01ms !important; }
  .msg-plain.is-mine,
  .sizer.is-live-entering > .msg-plain.is-mine{ animation-duration:.01ms !important; }
  .feed.filter-scan-active::before{ animation-duration:.12s !important; }
  .feed.filter-scan-active .feed-list{ animation-duration:.12s !important; }
  .step-pointer{ transition-duration:.01ms !important; }
  .step-pointer::before,.step-pointer-tip{ animation:none !important; }
}

